def main():
    manual = OUT / "manual_candidates.tsv"
    with manual.open(encoding="utf-8", newline="") as fh:
        reader = csv.DictReader(fh, delimiter="\t")
        fields = list(reader.fieldnames)
        rows = list(reader)
    for field in ("selection_status", "selection_reason", "replaces_code", "processing_note"):
        if field not in fields:
            fields.append(field)
    by_code = {r["code"]: r for r in rows}
    for code, reason in RESERVE.items():
        by_code[code]["selection_status"] = "reserve"
        by_code[code]["selection_reason"] = reason
    for code, note in NOTES.items():
        by_code[code]["processing_note"] = note
    # Correct the two historical coordinate errors from stored raster orientation.
    by_code["TP-E-114"]["box_1000"] = "340,350,715,560"
    by_code["TP-E-114"]["motif_class"] = "пятилопастной цветок"
    by_code["TP-E-114"]["description"] = "Темная пятилопастная кожаная фигура с овальной сердцевиной и желтой кромкой"
    by_code["TP-E-115"]["box_1000"] = "193,683,661,931"
    # Fill margins and use a closer angle of the same ornament where available.
    updates = {
        "TP-E-034": {"box_1000": "315,175,680,383"},
        "TP-E-046": {"box_1000": "410,330,594,605", "description": "Белый шестилепестковый цветок с желтой сердцевиной и шестью малыми синими долями"},
        "TP-E-050": {"box_1000": "420,330,573,540"},
        "TP-E-041": {"frame": "DSC9559", "box_1000": "132,270,344,539", "manual_note": "верхняя левая ветвь футляра; более крупный вид того же мотива DSC9559"},
        "TP-E-042": {"frame": "DSC9559", "box_1000": "465,586,731,865", "manual_note": "нижняя правая ветвь футляра; более крупный вид того же мотива DSC9559"},
        "TP-E-043": {"frame": "DSC9565", "box_1000": "279,272,605,586", "manual_note": "центральное переплетение пояса, более крупный кадр DSC9565"},
        "TP-E-044": {"frame": "DSC9565", "box_1000": "634,250,708,680", "manual_note": "мелкая наружная цепь справа на поясе, более крупный кадр DSC9565"},
        "TP-E-072": {"frame": "DSC9627", "box_1000": "85,177,471,586", "manual_note": "крупный цветок слева, тот же мотив из общего кадра DSC9626"},
        "TP-E-083": {"box_1000": "293,376,448,629"},
        "TP-E-085": {"box_1000": "409,330,565,620", "processing_note": "Выдели только полный средний овальный модуль с коричневой вставкой и кольцом голубых вставок. Соединительные шарики и соседние модули убрать; сохранить контуры и видимое число вставок."},
        "TP-E-106": {"box_1000": "389,229,591,330"},
    }
    for code, changes in updates.items():
        by_code[code].update(changes)
    for number, artifact, frame, box, cls, description, confidence, place, old, note in NEW:
        code = f"TP-E-{number:03}"
        if code in by_code:
            continue
        row = {field: "" for field in fields}
        row.update(code=code, artifact_code=artifact, frame=frame, box_1000=box,
                   motif_class=cls, description=description, motif_confidence=f"{confidence:.2f}",
                   crop_limitations="локальный фрагмент реального фото; плоская отрисовка требует сверки человеком",
                   manual_note=place, selection_status="active", replaces_code=old,
                   selection_reason="визуальный отбор ИИ; есть привязанная музейная табличка; требуется человек",
                   processing_note=note)
        rows.append(row)
    with manual.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=fields, delimiter="\t")
        writer.writeheader()
        writer.writerows(rows)
    print(json.dumps({"manual_rows": len(rows), "reserved": len(RESERVE), "new": len(NEW)}, ensure_ascii=False))


if __name__ == "__main__":
    main()
